def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for me, opp in history:
        if me == 'D':
            my_d += 1
        if opp == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    w = 8 if n >= 8 else n
    recent_d = 0
    for me, opp in history[-w:]:
        if opp == 'D':
            recent_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    resp_c = 0
    resp_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'D':
                resp_d += 1
            else:
                resp_c += 1

    if n >= 10 and opp_d * 4 >= 3 * n:
        return 'D'

    if last_opp == 'D':
        if n >= 2 and last_me == 'C' and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C' if rng.random() < 0.82 else 'D'

        if opp_d * 10 <= n * 2:
            p = 0.65
        elif opp_d * 10 <= n * 3:
            p = 0.50
        elif opp_d * 10 <= n * 4:
            p = 0.35
        elif opp_d * 10 <= n * 5:
            p = 0.22
        elif opp_d * 10 <= n * 7:
            p = 0.10
        else:
            p = 0.02

        if opp_d <= 1 and n <= 6:
            p = max(p, 0.45)
        if last_me == 'D':
            p += 0.18
        if opp_streak >= 4:
            p += 0.22
        if opp_streak >= 8:
            p += 0.18
        if recent_d >= 4:
            p -= 0.18
        if recent_d >= w:
            p -= 0.30
        if opp_d > my_d + 4 and recent_d >= 2:
            p -= 0.20
        if resp_d >= 3 and resp_d > resp_c:
            p -= 0.15

        if p < 0.0:
            p = 0.0
        if p > 0.92:
            p = 0.92

        return 'C' if rng.random() < p else 'D'

    if last_me == 'D':
        p = 0.0
        if opp_d == 0:
            p = 0.25
        if (opp_d == 0 and resp_c >= 1) or (resp_c >= 3 and resp_d == 0):
            p = 0.75
        if p > 0.0 and rng.random() < p:
            return 'D'
        return 'C'

    p = 0.0
    if (opp_d == 0 and resp_c >= 2) or (resp_c >= 3 and resp_d == 0):
        p = 0.18
        if n > 50:
            p += 0.18
        if opp_d == 0:
            p += 0.22
        if recent_d == 0:
            p += 0.08
    elif opp_d == 0 and my_d == 0 and n >= 40:
        p = 0.05
    elif recent_d >= 4:
        p = 0.35

    if p > 0.0 and rng.random() < p:
        return 'D'

    return 'C'
